#!/usr/bin/env python3

import json
import sys
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
TEST_PROMPT = "Reply with exactly one word: OK"
REQUEST_TIMEOUT = 30


def load_models(config_path):
    with open(config_path, "r", encoding="utf-8") as f:
        config = json.load(f)

    entries = None

    if isinstance(config, list):
        entries = config
    elif isinstance(config, dict):
        for key in ("models", "model_list", "data"):
            if isinstance(config.get(key), list):
                entries = config[key]
                break

    if entries is None:
        raise ValueError(
            "Could not find a model list in the JSON file. "
            "Supported formats: a top-level list, or an object with "
            "'models', 'model_list', or 'data'."
        )

    models = []
    for item in entries:
        model_name = None

        if isinstance(item, str):
            model_name = item.strip()

        elif isinstance(item, dict):
            for key in ("model_name", "model", "name", "id"):
                value = item.get(key)
                if isinstance(value, str) and value.strip():
                    model_name = value.strip()
                    break

            if not model_name:
                litellm_params = item.get("litellm_params")
                if isinstance(litellm_params, dict):
                    value = litellm_params.get("model")
                    if isinstance(value, str) and value.strip():
                        model_name = value.strip()

        if model_name:
            models.append(model_name)

    if not models:
        raise ValueError("No models found in config file.")

    return models


def send_request(model, include_temperature):
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": TEST_PROMPT}],
        "max_tokens": 20,
    }

    if include_temperature:
        payload["temperature"] = 0

    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        API_URL,
        data=data,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    start = time.time()
    try:
        with urllib.request.urlopen(req, timeout=REQUEST_TIMEOUT) as resp:
            body = resp.read().decode("utf-8", errors="replace")
        return True, time.time() - start, body, ""
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", errors="replace")
        return False, time.time() - start, body, "HTTP {}: {}".format(e.code, body)
    except urllib.error.URLError as e:
        return False, time.time() - start, "", "URL error: {}".format(e.reason)
    except Exception as e:
        return False, time.time() - start, "", "Error: {}".format(e)


def temperature_unsupported(text):
    text = (text or "").lower()
    if "temperature" not in text:
        return False

    hints = (
        "not supported",
        "unsupported",
        "does not support",
        "doesn't support",
        "not a valid",
        "unknown parameter",
        "unknown field",
        "unexpected keyword",
        "extra inputs are not permitted",
        "extra_forbidden",
    )
    return any(hint in text for hint in hints)


def extract_response_text(body):
    try:
        data = json.loads(body)
    except Exception as e:
        return None, "Invalid JSON response: {}".format(e)

    choices = data.get("choices")
    if isinstance(choices, list) and choices:
        first = choices[0]
        if isinstance(first, dict):
            message = first.get("message")
            if isinstance(message, dict):
                content = message.get("content")
                if isinstance(content, str):
                    return content.strip(), ""
                if isinstance(content, list):
                    parts = []
                    for part in content:
                        if isinstance(part, dict):
                            text = part.get("text")
                            if isinstance(text, str):
                                parts.append(text)
                    if parts:
                        return "".join(parts).strip(), ""

            text = first.get("text")
            if isinstance(text, str):
                return text.strip(), ""

    error_obj = data.get("error")
    if error_obj:
        if isinstance(error_obj, dict):
            return None, error_obj.get("message") or json.dumps(error_obj)
        return None, str(error_obj)

    return None, "No response content found"


def preview(text, limit=50):
    text = "" if text is None else " ".join(str(text).split())
    if len(text) <= limit:
        return text
    return text[: limit - 3] + "..."


def test_model(model):
    overall_start = time.time()

    ok, _, body, err = send_request(model, include_temperature=True)

    if not ok and temperature_unsupported((err or "") + " " + (body or "")):
        ok, _, body, err = send_request(model, include_temperature=False)

    latency = time.time() - overall_start

    if ok:
        response_text, parse_err = extract_response_text(body)
        if response_text is None:
            return {
                "model": model,
                "status": "FAIL",
                "latency": latency,
                "response": preview(parse_err),
            }

        return {
            "model": model,
            "status": "PASS" if response_text == "OK" else "FAIL",
            "latency": latency,
            "response": preview(response_text),
        }

    return {
        "model": model,
        "status": "FAIL",
        "latency": latency,
        "response": preview(err or body or "Request failed"),
    }


def print_table(results):
    headers = ("Model", "Status", "Latency", "Response")
    rows = []

    for r in results:
        rows.append((
            r["model"],
            r["status"],
            "{:.2f}s".format(r["latency"]),
            r["response"],
        ))

    widths = [len(h) for h in headers]
    for row in rows:
        for i, value in enumerate(row):
            widths[i] = max(widths[i], len(value))

    header_line = "  ".join([
        headers[0].ljust(widths[0]),
        headers[1].ljust(widths[1]),
        headers[2].ljust(widths[2]),
        headers[3].ljust(widths[3]),
    ])
    separator_line = "  ".join("-" * w for w in widths)

    print(header_line)
    print(separator_line)

    for row in rows:
        print("  ".join([
            row[0].ljust(widths[0]),
            row[1].ljust(widths[1]),
            row[2].ljust(widths[2]),
            row[3].ljust(widths[3]),
        ]))


def main():
    if len(sys.argv) != 2:
        print("Usage: python {} <config.json>".format(sys.argv[0]), file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        models = load_models(config_path)
    except Exception as e:
        print("Failed to load models: {}".format(e), file=sys.stderr)
        sys.exit(1)

    results = []
    for model in models:
        results.append(test_model(model))

    print_table(results)

    passed = sum(1 for r in results if r["status"] == "PASS")
    failed = len(results) - passed
    print()
    print("Total: {} models | ✅ {} working | ❌ {} failed".format(len(results), passed, failed))


if __name__ == "__main__":
    main()
